        strokeWidth={1.8}
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
      />
    </Svg>
  )
}

"""
assert k.count(esk_ikon) == 1
k = k.replace(esk_ikon, "")

# 3c) props
esk = """  silOnayiAcik?: boolean
  /** Verilmezse silme dugmesi hic cizilmez. */
  onSilOnayi?: (id: string) => void
  onSil?: (id: string) => void
}) {"""
assert k.count(esk) == 1
k = k.replace(
    esk,
