  await new Promise((c) => setTimeout(c, 5000))

  await sayfa.goto(`${TABAN}/`, { waitUntil: 'networkidle0', timeout: 60000 })
  await sayfa.evaluate(() => document.fonts.ready)
  await new Promise((c) => setTimeout(c, 1800))

  const bulundu = await sayfa.evaluate(() => {
    const d = document.querySelector('[aria-label="Yorumlar"]')
    if (!d) return false
    d.dispatchEvent(new MouseEvent('click', { bubbles: true }))
    return true
  })
  console.log('yorum ikonu bulundu:', bulundu)
  await new Promise((c) => setTimeout(c, 1500))
  await sayfa.screenshot({ path: '../tasarim/yeni-yorumlar.png' })
  console.log('goruntu alindi')
} finally {
  await tarayici.close()
}

