"""Koyu mod gecisi, 2. adim: kancalari bilesenlerin icine koy.

Yalnizca MODUL DUZEYINDEKI ve JSX donduren fonksiyonlara dokunuyor.
Ic ice fonksiyonlara (geri cagrilar) dokunmak kancalari kosullu hale
getirir ve React kurallarini bozardi; bu yuzden sart JSX donduruyor
OLMASI ve satir basinda tanimlanmis olmasi.
"""
import io
import os
import re

os.chdir(r"C:\Users\orcns\projects\cloud\mobil")

BILDIRIM = re.compile(r"^(?:export default function|export function|function) ([A-Za-z0-9_]+)\(", re.M)


def govde_araligi(k: str, bas: int):
    """Parametre parantezini gecip govdenin { } araligini bulur."""
    i = k.index("(", bas)
    derinlik = 0
    while i < len(k):
        if k[i] == "(":
            derinlik += 1
        elif k[i] == ")":
            derinlik -= 1
            if derinlik == 0:
                break
        i += 1
    # parametreden sonraki ilk suslu parantez govdenin acilisi
    j = k.index("{", i)
    derinlik = 0
    s = j
    while s < len(k):
        if k[s] == "{":
            derinlik += 1
        elif k[s] == "}":
            derinlik -= 1
            if derinlik == 0:
                return j, s
        s += 1
    raise ValueError("govde kapanisi bulunamadi")


sayac = {"dosya": 0, "bilesen": 0}
for kok, _, adlar in os.walk("src"):
    for ad in adlar:
        if not ad.endswith(".tsx"):
            continue
        yol = os.path.join(kok, ad).replace("\\", "/")
        k = io.open(yol, encoding="utf-8").read()
        if "stilleriYap" not in k and "useRenk" not in k:
            continue

        eklendi = False
        # Sondan basa: eklemeler onceki konumlari kaydirmasin.
        for m in reversed(list(BILDIRIM.finditer(k))):
            try:
                acilis, kapanis = govde_araligi(k, m.start())
            except ValueError:
                continue
            govde = k[acilis:kapanis]
            jsxMi = ("</" in govde) or ("/>" in govde)
            if not jsxMi:
                continue

            satirlar = []
            if re.search(r"\brenk\.", govde) and "const renk = useRenk()" not in govde:
                satirlar.append("  const renk = useRenk()")
            if re.search(r"\bstiller\.", govde) and "useStiller(stilleriYap)" not in govde:
                satirlar.append("  const stiller = useStiller(stilleriYap)")
            if not satirlar:
                continue

            k = k[: acilis + 1] + "\n" + "\n".join(satirlar) + k[acilis + 1:]
            eklendi = True
            sayac["bilesen"] += 1

        if eklendi:
            io.open(yol, "w", encoding="utf-8", newline="\n").write(k)
            sayac["dosya"] += 1

print(f"{sayac['dosya']} dosya, {sayac['bilesen']} bilesen")

